<template>
  <div v-if="password && password.length > 0" class="password-checklist">
    <div
      v-for="(rule, index) in computedRules"
      :key="index"
      class="password-rule"
      :class="{
        'rule-met': rule.met,
        'rule-failed': !rule.met,
      }"
    >
      <Icon
        :icon="rule.met ? 'mdi:check-circle' : 'mdi:close-circle'"
        class="size-4"
      />
      <span class="rule-text">{{ rule.message }}</span>
    </div>
  </div>
</template>

<script lang="ts">
import { defineComponent, type PropType } from 'vue';
import { specialChars } from 'src/constants';

interface PasswordRule {
  message: string;
  met: boolean;
}

export default defineComponent({
  name: 'PasswordChecklist',
  props: {
    password: {
      type: String,
      default: '',
    },
  },
  computed: {
    computedRules(): PasswordRule[] {
      const pwd = this.password || '';
      return [
        { message: this.$t('length'), met: pwd.length >= 8 },
        { message: this.$t('password_length_maximum'), met: pwd.length > 0 && pwd.length <= 20 },
        { message: this.$t('uppercase'), met: /[A-Z]/.test(pwd) },
        { message: this.$t('lowercase'), met: /[a-z]/.test(pwd) },
        { message: this.$t('password_check_number'), met: /\d/.test(pwd) },
        { message: this.$t('special'), met: new RegExp(`[${specialChars}]`).test(pwd) },
      ];
    },
    allMet(): boolean {
      return this.computedRules.every((r) => r.met);
    },
  },
  watch: {
    allMet(val: boolean) {
      this.$emit('update:valid', val);
    },
  },
  emits: ['update:valid'],
});
</script>

<style scoped lang="scss">
.password-checklist {
  padding: 0.75rem;
  border-radius: 0.5rem;
  background-color: var(--muted);
  border: 1px solid var(--border);
}

.password-rule {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.125rem 0;
  font-size: 0.8125rem;
  transition: color 0.15s ease;
}

.rule-met {
  color: var(--success);
}

.rule-failed {
  color: var(--destructive);
}

.rule-text {
  line-height: 1.4;
}
</style>
